.shine {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-inline-start: auto;
  margin-inline-end: auto;
  margin-block-start: 40px;
  color: #00091c;
  font-family: Oi, cursive;
  font-weight: 400;
  font-size: clamp(22px, 5vw, 90px);
  background:
    radial-gradient(
      #fff 0%,
      #3cf 4%,
      #00bfff 12.25%,
      #07f 31.25%,
      #00091c 50%
    );
